import AxeBuilder from '@axe-core/playwright'
import { expect, test } from '@playwright/test'

/** 报告页与训练计划页的无障碍基线（serious / critical 为 0）。 */

const RULES = {
  'color-contrast': { enabled: true },
  'label': { enabled: true },
  'button-name': { enabled: true },
  'link-name': { enabled: true },
  'html-has-lang': { enabled: true },
  'document-title': { enabled: true },
  'heading-order': { enabled: true },
  'image-alt': { enabled: true },
  'aria-allowed-attr': { enabled: true },
  'aria-hidden-focus': { enabled: true },
}

async function scan(page: import('@playwright/test').Page, name: string) {
  await page.addStyleTag({ content: '*,*::before,*::after{animation:none!important;transition:none!important}' })
  await page.waitForTimeout(400)
  const results = await new AxeBuilder({ page }).options({ rules: RULES }).analyze()
  const blocking = results.violations.filter((item) => item.impact === 'serious' || item.impact === 'critical')
  const summary = blocking.map((item) => ({
    id: item.id,
    impact: item.impact,
    nodes: item.nodes.length,
    help: item.help,
    targets: item.nodes.slice(0, 3).map((node) => node.target.join(' ')),
  }))
  expect(summary, `${name} 存在无障碍问题`).toEqual([])
}

test('报告页与计划页无障碍', async ({ page, request }) => {
  test.setTimeout(180_000)
  const email = `a11y-rp-${Date.now()}@example.com`
  const password = 'AxeReport123!'

  await page.goto('/login')
  await page.getByRole('button', { name: '注册' }).first().click()
  await page.locator('input[name="displayName"]').fill('报告无障碍')
  await page.locator('input[name="email"]').fill(email)
  await page.locator('input[name="password"]').fill(password)
  await page.locator('input[name="confirmPassword"]').fill(password)
  await page.getByRole('checkbox', { name: '我已阅读并同意', exact: true }).check()
  await page.locator('button[type="submit"]').click()
  await expect(page.getByRole('link', { name: '场景训练' })).toBeVisible()

  const login = await request.post('/api/v1/auth/login', { data: { email, password } })
  const token = (await login.json()).data.accessToken
  const headers = { Authorization: `Bearer ${token}` }
  const scenes = await (await request.get('/api/v1/scenes?size=1', { headers })).json()
  const sceneId = scenes.data[0].id
  const created = await request.post('/api/v1/training-sessions', { data: { sceneId }, headers })
  const sessionId = (await created.json()).data.id

  for (const content of [
    '我有三段实习，主要做后端开发，最近做过订单系统的性能优化。',
    '项目的难点是缓存一致性和慢查询，我把接口从 800 毫秒降到了 200 毫秒。',
  ]) {
    const reply = await request.post(`/api/v1/training-sessions/${sessionId}/messages/complete`, {
      data: { content },
      headers,
      timeout: 90_000,
    })
    expect(reply.status()).toBe(200)
  }
  const finished = await request.post(`/api/v1/training-sessions/${sessionId}/finish`, { headers, timeout: 120_000 })
  expect(finished.status()).toBe(200)

  await page.goto(`/report/${sessionId}`)
  await expect(page.getByRole('heading', { name: /训练报告|这一场|这次表达/ }).first()).toBeVisible()
  await scan(page, '训练报告页')

  await page.goto('/plan')
  await expect(page.locator('main')).toBeVisible()
  await scan(page, '训练计划页')
})

import { expect, test, type Page } from '@playwright/test'
import { readFile } from 'node:fs/promises'

async function mockAdmin(page: Page) {
  const scene = { id: 'scene-admin-test', category: '技术一面', title: '后端项目面试', industry: '互联网', position: '后端工程师', roleName: '技术面试官', difficulty: '中级', background: '围绕候选人的真实项目经历进行追问。', goal: '说明个人职责、技术方案和验证过程。', tags: ['项目'], openingLine: '请介绍你的项目。', coreIdea: '通过具体事实验证项目贡献', active: true, questionBank: Array.from({ length: 5 }, (_, i) => ({ text: `第 ${i + 1} 道原有问题，请说明实际依据。`, dimension: '信息完整', difficulty: '中级' })) }
  const courses = [{ id: 'course-test', title: '项目表达方法', dimension: '内容与逻辑', minutes: 15, description: '围绕真实项目讲清个人职责。', content: '先说明结论；提供个人行动与事实依据；说明结果、验证过程和适用边界。', active: true }]
  const savedScenes: Array<{ questionBank: Array<{ text: string; dimension: string | null; difficulty: string | null }> }> = []
  const savedCourses: Array<{ title: string; dimension: string; active: boolean }> = []
  const pageErrors: string[] = []
  page.on('pageerror', (error) => pageErrors.push(error.message))
  await page.route('**/api/v1/**', async (route) => {
    const path = new URL(route.request().url()).pathname.replace('/api/v1', '')
    const method = route.request().method()
    let data: unknown = []
    if (path === '/auth/refresh') data = { accessToken: 'admin-test-token', user: { id: 'admin-test', email: 'admin-test@example.com', displayName: '管理验收', role: 'ADMIN', emailVerified: true, bio: null, avatar: null } }
    else if (path === '/admin/overview') data = { users: 0, activeUsers: 0, scenes: 1, activeScenes: 1, courses: courses.length, activeCourses: courses.filter((item) => item.active).length, sessions: 0, averageScore: 0 }
    else if (path === `/admin/scenes/${scene.id}` && method === 'PATCH') {
      const payload = route.request().postDataJSON()
      savedScenes.push(payload)
      Object.assign(scene, payload)
      data = { id: scene.id, active: true }
    } else if (path === '/admin/scenes') data = [scene]
    else if (path === '/admin/courses' && method === 'POST') {
      const payload = route.request().postDataJSON()
      savedCourses.push(payload)
      courses.push({ ...payload, id: 'course-new' })
      data = { id: 'course-new' }
    } else if (path.startsWith('/admin/courses/') && method === 'PATCH') {
      const payload = route.request().postDataJSON()
      savedCourses.push(payload)
      Object.assign(courses.find((item) => path.endsWith(`/${item.id}`))!, payload)
      data = { id: path.split('/').pop() }
    } else if (path === '/admin/courses') data = courses
    else if (path === '/admin/question-coverage') data = { totalScenes: 1, scenesWithBank: 1, scenesWithoutBank: 0, totalQuestions: scene.questionBank.length, neverTrained: 1, items: [] }
    else if (path === '/admin/recordings') data = { count: 0, totalBytes: 0, totalMb: 0, retentionDays: 30 }
    else if (path === '/admin/tasks') data = [{ id: 'old-task', kind: 'VIDEO_INTERVIEW', status: 'DONE', progress: 100, stage: '完成', error: null, email: 'history@example.com', createdAt: '2026-11-01T00:00:00Z', updatedAt: '2026-11-01T01:00:00Z' }]
    return route.fulfill({ json: { data, meta: {} } })
  })
  await page.goto('/admin')
  await expect(page.getByRole('button', { name: '刷新数据', exact: true })).toBeEnabled()
  return { savedScenes, savedCourses, pageErrors }
}

test('旧分析结果只读保留，管理页不再提供重跑按钮', async ({ page }) => {
  const mock = await mockAdmin(page)
  await page.getByRole('button', { name: '历史分析记录', exact: true }).click()
  await expect(page.getByRole('heading', { name: '历史分析记录', exact: true })).toBeVisible()
  await expect(page.locator('.tasks-table')).toContainText('history@example.com')
  await expect(page.getByRole('button', { name: /重跑|再跑一次/ })).toHaveCount(0)
  await expect(page.locator('.tasks-head')).toContainText('旧录像上传分析已停用')
  expect(mock.pageErrors).toEqual([])
})

test('题库合并到场景设计，超过三题和题目属性均完整保存', async ({ page }) => {
  const mock = await mockAdmin(page)
  await expect(page.getByRole('button', { name: '题库管理', exact: true })).toHaveCount(0)
  await page.getByRole('button', { name: '场景设计', exact: true }).click()
  await page.getByRole('searchbox', { name: '搜索场景', exact: true }).fill('后端')
  await page.locator('.scene-card').getByRole('button', { name: '编辑', exact: true }).click()
  await expect(page.locator('.bank-row')).toHaveCount(5)
  await page.getByLabel('第 4 题正文', { exact: true }).fill('第四题修改后仍应保留，不能被截断。')
  await page.getByRole('button', { name: '+ 添加一题', exact: true }).click()
  await page.getByLabel('第 6 题正文', { exact: true }).fill('新增问题，请解释方案的边界条件。')
  await page.getByRole('combobox', { name: '第 6 题考察维度', exact: true }).click()
  await page.getByRole('option', { name: '贴合问题', exact: true }).click()
  await page.getByRole('combobox', { name: '第 6 题难度', exact: true }).click()
  await page.getByRole('option', { name: '进阶', exact: true }).click()
  await page.getByRole('button', { name: '保存修改', exact: true }).click()
  await expect.poll(() => mock.savedScenes.length).toBe(1)
  expect(mock.savedScenes[0].questionBank).toHaveLength(6)
  expect(mock.savedScenes[0].questionBank[3]).toEqual({ text: '第四题修改后仍应保留，不能被截断。', dimension: '信息完整', difficulty: '中级' })
  expect(mock.savedScenes[0].questionBank[5]).toEqual({ text: '新增问题，请解释方案的边界条件。', dimension: '贴合问题', difficulty: '进阶' })
  await page.locator('.scene-card').getByRole('button', { name: '编辑', exact: true }).click()
  await expect(page.locator('.bank-row')).toHaveCount(6)
  expect(mock.pageErrors).toEqual([])
})

test('场景题目导入导出支持二十题，超限或损坏导入不覆盖原内容', async ({ page }) => {
  const mock = await mockAdmin(page)
  await page.getByRole('button', { name: '场景设计', exact: true }).click()
  await page.locator('.scene-card').getByRole('button', { name: '编辑', exact: true }).click()
  const questions = Array.from({ length: 20 }, (_, i) => ({ text: `导入第 ${i + 1} 道项目问题。`, dimension: '内容与逻辑', difficulty: '进阶' }))
  const input = page.getByLabel('导入场景题目', { exact: true })
  await input.setInputFiles({ name: 'questions.json', mimeType: 'application/json', buffer: Buffer.from(JSON.stringify(questions)) })
  await expect(page.locator('.bank-row')).toHaveCount(20)
  await expect(page.getByRole('button', { name: '+ 添加一题', exact: true })).toBeDisabled()
  const downloadPromise = page.waitForEvent('download')
  await page.getByRole('button', { name: '导出', exact: true }).click()
  const download = await downloadPromise
  const exported = JSON.parse(await readFile((await download.path())!, 'utf8'))
  expect(exported).toEqual(questions)
  await input.setInputFiles({ name: 'overflow.json', mimeType: 'application/json', buffer: Buffer.from(JSON.stringify([...questions, questions[0]])) })
  await expect(page.getByRole('alert')).toContainText('最多 20 道题')
  await expect(page.locator('.bank-row')).toHaveCount(20)
  await input.setInputFiles({ name: 'broken.json', mimeType: 'application/json', buffer: Buffer.from('[null]') })
  await expect(page.getByRole('alert')).toContainText('每道题需要 text 正文')
  await expect(page.getByLabel('第 20 题正文', { exact: true })).toHaveValue(questions[19].text)
  await page.getByRole('button', { name: '保存修改', exact: true }).click()
  await expect.poll(() => mock.savedScenes.length).toBe(1)
  expect(mock.savedScenes[0].questionBank).toEqual(questions)
  expect(mock.pageErrors).toEqual([])
})

test('微课内容管理保留新增编辑停用，默认使用当前评分维度', async ({ page }) => {
  const mock = await mockAdmin(page)
  await expect(page.getByRole('button', { name: '微课素材', exact: true })).toHaveCount(0)
  await page.getByRole('button', { name: '微课内容管理', exact: true }).click()
  await expect(page.getByRole('heading', { name: '微课内容管理', exact: true })).toBeVisible()
  await page.getByRole('button', { name: '新增微课', exact: true }).click()
  await expect(page.getByRole('combobox', { name: '课程维度', exact: true })).toContainText('内容与逻辑')
  await page.getByLabel('课程名称', { exact: true }).fill('管理员新增课程底稿')
  await page.getByLabel(/课程正文（生成底稿）/).fill('先说明核心结论；引用真实项目事实与个人行动；最后提供验证结果和边界。')
  await page.getByRole('button', { name: '创建微课', exact: true }).click()
  await expect.poll(() => mock.savedCourses.length).toBe(1)
  expect(mock.savedCourses[0].dimension).toBe('内容与逻辑')
  const row = page.locator('.course-card').filter({ hasText: '管理员新增课程底稿' })
  await row.getByRole('button', { name: '编辑', exact: true }).click()
  await page.getByLabel('课程名称', { exact: true }).fill('管理员更新课程底稿')
  await page.getByRole('button', { name: '保存修改', exact: true }).click()
  await expect.poll(() => mock.savedCourses.length).toBe(2)
  page.once('dialog', (dialog) => dialog.accept())
  await page.locator('.course-card').filter({ hasText: '管理员更新课程底稿' }).getByRole('button', { name: '停用', exact: true }).click()
  await expect.poll(() => mock.savedCourses.length).toBe(3)
  expect(mock.savedCourses[2].active).toBe(false)
  await expect(page.locator('.course-card').filter({ hasText: '管理员更新课程底稿' })).toContainText('已停用')
  await page.getByRole('button', { name: '题目覆盖', exact: true }).click()
  await expect(page.getByText('场景总数', { exact: true })).toBeVisible()
  expect(mock.pageErrors).toEqual([])
})

import { expect, test } from '@playwright/test'

test('数字人默认顺序保持，开发形象选择优先且生产忽略 URL 覆盖', async ({ page }) => {
  await page.goto('/login')
  const orders = await page.evaluate(async () => {
    const moduleUrl = '/src/lib/avatarConfig.ts'
    const { avatarOrder } = await import(/* @vite-ignore */ moduleUrl)
    return {
      defaults: avatarOrder('auto', false, ''),
      local: avatarOrder('live2d', false, ''),
      dev: avatarOrder('auto', true, '?avatar=vrm'),
      production: avatarOrder('photo', false, '?avatar=human'),
      invalid: avatarOrder('unrecognized', false, ''),
    }
  })
  expect(orders.defaults).toEqual(['simli', 'human', 'photo', 'live2d'])
  expect(orders.local[0]).toBe('live2d')
  expect(orders.dev[0]).toBe('vrm')
  expect(orders.production[0]).toBe('photo')
  expect(orders.invalid).toEqual(orders.defaults)
  expect(new Set(orders.dev).size).toBe(orders.dev.length)
})

import { expect, test, type Page } from '@playwright/test'
import { fileURLToPath } from 'node:url'

// 3 秒纯色无声视频，由 ffmpeg 生成，不依赖真实课程或云端渲染。
const videoFixture = fileURLToPath(new URL('./fixtures/lesson-replay.mp4', import.meta.url))
const audioVideoFixture = fileURLToPath(new URL('./fixtures/avatar-speech.mp4', import.meta.url))
const lesson = {
  title: '先给结论，再补事实', intro: '把回答组织成清楚的结论、具体的事实和下一步行动。', aiGenerated: false,
  steps: ['先给结论', '补充事实', '明确行动'].map((title) => ({ title, explanation: '围绕原问题清楚表达，用真实经历说明自己的判断。', example: '我的结论是先修复问题，我负责验证后同步处理结果。' })),
  exercise: '结合最近一次项目经历，说明你的结论、依据和后续行动。',
}

async function mockCourse(page: Page, options: { cached?: boolean; completed?: boolean; cacheFails?: boolean; delay?: boolean; audio?: boolean; progress?: boolean } = {}) {
  const state = { renders: 0, cacheReads: 0, cached: options.cached ?? true, changed: false, errors: [] as string[] }
  const task = { key: 'course', day: 1, actionType: 'COURSE', task: '学习微课', lesson, completed: options.completed ?? false, completedSteps: options.completed ? [0, 1, 2] : [], learningProgress: options.completed ? 100 : 0, learned: options.completed ?? false, practicePassed: options.completed ?? false }
  const plan = { id: 'replay-plan', sequence: 1, title: '表达提升计划', focusDimension: '内容与逻辑', status: options.completed ? 'COMPLETED' : 'ACTIVE', progress: options.completed ? 100 : 0, createdAt: '2026-11-12T02:00:00Z', tasks: [task] }
  const chapters = [{ title: '先给结论', start: 0, duration: 1 }, { title: '补充事实', start: 1, duration: 2 }]
  const videoState = (override?: { status: string; progress: number }) => override
    ? { jobId: 'replay-job', status: override.status, progress: override.progress, stage: null, url: null, chapters: [], error: null }
    : state.cached
      ? { jobId: 'replay-job', status: 'DONE', progress: 100, stage: '已完成', url: '/media/lessons/replay-saved.mp4', chapters, error: null }
      : { jobId: null, status: 'PENDING', progress: 0, stage: null, url: null, chapters: [], error: null }
  page.on('pageerror', (error) => state.errors.push(error.message))
  await page.route('**/media/lessons/**', (route) => route.fulfill({ path: options.audio ? audioVideoFixture : videoFixture, contentType: 'video/mp4' }))
  await page.route('**/api/v1/**', async (route) => {
    const path = new URL(route.request().url()).pathname
    let data: unknown = []
    if (path.endsWith('/auth/refresh')) data = { accessToken: 'course-test', user: { id: 'test', role: 'STUDENT', displayName: '课程回看' } }
    else if (path.endsWith('/training-plans/replay-plan')) data = plan
    else if (path.endsWith('/lesson/video/state')) {
      // 组件用 GET /training-plans/{id}/lesson/video/state 读进度，返回 LessonVideoState。
      // 计划页（/plans/...）的轮询不计入缓存读取次数，只统计课程页（/plan-lesson）的读取。
      const fromLessonPage = (route.request().frame()?.url() ?? '').includes('/plan-lesson')
      if (fromLessonPage) {
        state.cacheReads++
        if (options.delay) await new Promise((resolve) => setTimeout(resolve, 250))
        if (options.cacheFails && state.cacheReads === 1) { await route.fulfill({ status: 503, json: { detail: '暂时无法读取视频' } }); return }
      }
      data = videoState()
    } else if (path.endsWith('/lesson/video')) {
      // POST 触发渲染；GET 是旧接口，保留兜底
      if (route.request().method() === 'POST') {
        state.renders++
        state.cached = true
        // progress 模式下先返回「生成中」，下一次 GET /state 才给 DONE，用于断言进度态
        if (options.progress) { await route.fulfill({ json: { data: videoState({ status: 'RUNNING', progress: 40 }), meta: {} } }); return }
      }
      data = videoState()
    } else if (path.endsWith('/lesson')) {
      if (route.request().postDataJSON().force) { state.changed = true; state.cached = false }
      data = { lesson: state.changed ? { ...lesson, title: '换课后的新内容' } : lesson, source: { title: lesson.title, description: '', content: '' } }
    } else { await route.fulfill({ status: 404, json: { detail: '此测试未提供该接口' } }); return }
    await route.fulfill({ json: { data, meta: {} } })
  })
  return state
}

test('历史计划微课直接播放，返回和刷新后均无需重新生成', async ({ page }) => {
  const state = await mockCourse(page, { completed: true, delay: true })
  await page.goto('/plans/replay-plan')
  await page.getByRole('link', { name: '回看 →', exact: true }).click()
  await expect(page.getByText('正在读取视频生成进度…', { exact: true })).toBeVisible()
  await expect(page.getByRole('button', { name: '生成视频', exact: true })).toHaveCount(0)
  const video = page.locator('.stage video')
  await expect(video).toHaveAttribute('src', '/media/lessons/replay-saved.mp4')
  await video.evaluate(async (element: HTMLVideoElement) => { await element.play() })
  await expect.poll(() => video.evaluate((element: HTMLVideoElement) => element.currentTime)).toBeGreaterThan(.4)
  await page.getByRole('button', { name: /补充事实/ }).click()
  await expect.poll(() => video.evaluate((element: HTMLVideoElement) => element.currentTime)).toBeGreaterThanOrEqual(1)
  await page.getByRole('link', { name: '← 返回训练计划', exact: true }).click()
  await page.getByRole('link', { name: '回看 →', exact: true }).click()
  await expect(video).toBeVisible()
  await page.reload()
  await expect(video).toHaveAttribute('src', '/media/lessons/replay-saved.mp4')
  expect(state.cacheReads).toBe(3)
  expect(state.renders).toBe(0)
  await expect(page.getByRole('button', { name: '换一门', exact: true })).toHaveCount(0)
  expect(state.errors).toEqual([])
})

test('首次进入课程自动触发视频生成，重新进入后自动复用', async ({ page }) => {
  const state = await mockCourse(page, { cached: false, progress: true })
  const posts: string[] = []
  page.on('request', (request) => {
    if (request.method() === 'POST' && request.url().includes('/lesson/video')) posts.push(request.url())
  })
  await page.goto('/plan-lesson?planId=replay-plan&taskKey=course')
  // 不点任何按钮：PENDING 时组件自己补一次触发，直接进入进度态
  await expect(page.getByText('正在生成这节课', { exact: true })).toBeVisible()
  await expect(page.getByRole('progressbar', { name: '微课视频生成进度' })).toHaveAttribute('aria-valuenow', '40')
  expect(posts).toHaveLength(1)
  await expect(page.getByRole('button', { name: '生成视频', exact: true })).toHaveCount(0)
  await expect(page.locator('.stage video')).toBeVisible({ timeout: 10_000 })
  await page.reload()
  await expect(page.locator('.stage video')).toBeVisible()
  expect(state.renders).toBe(1)
  expect(state.errors).toEqual([])
})

test('视频读取失败显示重试入口，不误提示重新生成', async ({ page }) => {
  const state = await mockCourse(page, { cacheFails: true })
  await page.goto('/plan-lesson?planId=replay-plan&taskKey=course')
  await expect(page.getByRole('alert')).toContainText('暂时无法读取视频')
  await expect(page.getByRole('button', { name: '生成视频', exact: true })).toHaveCount(0)
