import { readonly, shallowRef } from 'vue'

import { api, setAccessToken } from '@/lib/api'
import type { ApiEnvelope, User } from '@/lib/types'

type AuthResult = { accessToken: string; user: User }

const user = shallowRef<User | null>(null)
const initialized = shallowRef(false)
const loading = shallowRef(false)

export function useAuth() {
  function applyAuthResult(result: AuthResult): void {
    setAccessToken(result.accessToken)
    user.value = result.user
    initialized.value = true
  }

  async function login(email: string, password: string): Promise<void> {
    loading.value = true
    try {
      const response = await api.post<ApiEnvelope<AuthResult>>('/auth/login', { email, password })
      applyAuthResult(response.data.data)
    } finally {
      loading.value = false
    }
  }


  async function register(email: string, password: string, displayName: string): Promise<void> {
    loading.value = true
    try {
      const response = await api.post<ApiEnvelope<AuthResult>>('/auth/register', {
        email,
        password,
        displayName,
        // AuthForm 未勾选《隐私政策》时不会提交，请求到达这里即表示已同意
        consent: true,
      })
      applyAuthResult(response.data.data)
    } finally {
      loading.value = false
    }
  }

  async function restore(): Promise<void> {
    if (initialized.value) return
    try {
      const refreshed = await api.post<ApiEnvelope<{ accessToken: string; user: User }>>('/auth/refresh')
      setAccessToken(refreshed.data.data.accessToken)
      user.value = refreshed.data.data.user
    } catch {
      user.value = null
      setAccessToken('')
    } finally {
      initialized.value = true
    }
  }

  async function refreshUser(): Promise<void> {
    if (!user.value) return
    user.value = (await api.get<ApiEnvelope<User>>('/auth/me')).data.data
  }

  async function logout(): Promise<void> {
    try {
      await api.post('/auth/logout')
    } finally {
      setAccessToken('')
      user.value = null
    }
  }

  function applyAvatar(avatar: string | null): void {
    if (user.value) user.value = { ...user.value, avatar }
  }

  async function updateProfile(displayName: string, bio: string | null): Promise<void> {
    const response = await api.patch<ApiEnvelope<User>>('/auth/me', { displayName, bio })
    user.value = response.data.data
  }

  return {
    user: readonly(user),
    initialized: readonly(initialized),
    loading: readonly(loading),
    login,
    register,
    restore,
    logout,
    refreshUser,
    updateProfile,
    applyAvatar,
  }
}

import { onBeforeUnmount, onMounted, readonly, shallowRef } from 'vue'

interface RecognitionResult {
  isFinal: boolean
  0: { transcript: string }
}

interface RecognitionEvent {
  results: ArrayLike<RecognitionResult>
}

interface BrowserRecognition {
  lang: string
  continuous: boolean
  interimResults: boolean
  onstart: (() => void) | null
  onresult: ((event: RecognitionEvent) => void) | null
  onerror: ((event: { error: string }) => void) | null
  onend: (() => void) | null
  start(): void
  stop(): void
  abort(): void
}

type RecognitionConstructor = new () => BrowserRecognition
type SpeechWindow = Window & {
  SpeechRecognition?: RecognitionConstructor
  webkitSpeechRecognition?: RecognitionConstructor
}

export function useBrowserSpeech() {
  const available = shallowRef(false)
  const secureContext = shallowRef(true)
  const listening = shallowRef(false)
  const speaking = shallowRef(false)
  const transcript = shallowRef('')
  const interim = shallowRef('')
  const error = shallowRef('')
  const autoRead = shallowRef(true)
  let recognition: BrowserRecognition | null = null

  onMounted(() => {
    const browser = window as SpeechWindow
    available.value = Boolean(browser.SpeechRecognition || browser.webkitSpeechRecognition)
    secureContext.value = window.isSecureContext
  })

  function start(): void {
    const browser = window as SpeechWindow
    const Constructor = browser.SpeechRecognition || browser.webkitSpeechRecognition
    if (!Constructor) {
      error.value = '当前浏览器不支持网页语音识别，请使用最新版 Chrome / Edge，或切换文字模式。'
      return
    }
    stopSpeaking()
    recognition?.abort()
    transcript.value = ''
    interim.value = ''
    error.value = ''
    const instance = new Constructor()
    instance.lang = 'zh-CN'
    instance.continuous = false
    instance.interimResults = true
    instance.onstart = () => { listening.value = true }
    instance.onresult = (event) => {
      let finalText = ''
      let interimText = ''
      for (let index = 0; index < event.results.length; index += 1) {
        const result = event.results[index]
        if (!result) continue
        if (result.isFinal) finalText += result[0].transcript
        else interimText += result[0].transcript
      }
      transcript.value = finalText.trim()
      interim.value = interimText.trim()
    }
    instance.onerror = (event) => {
      const messages: Record<string, string> = {
        'not-allowed': '麦克风权限被拒绝。请在 Chrome 网站设置中允许麦克风；若使用局域网 HTTP 地址，请换用 HTTPS 测试地址。',
        'service-not-allowed': '语音识别服务不可用。请检查网络，或切换文字模式。',
        'audio-capture': '没有检测到可用麦克风，请检查设备与浏览器权限。',
        network: '语音识别服务连接失败，请检查网络后重试。',
        'no-speech': '没有听到语音，请靠近麦克风再试一次。',
      }
      error.value = messages[event.error] ?? '语音识别没有完成，请重试或切换文字模式。'
    }
    instance.onend = () => {
      listening.value = false
      if (!transcript.value && interim.value) transcript.value = interim.value
      interim.value = ''
      if (recognition === instance) recognition = null
    }
    recognition = instance
    try { instance.start() }
    catch { recognition = null; error.value = '无法启动麦克风，请检查浏览器权限后重试。' }
  }

  function stop(): void {
    recognition?.stop()
  }

  function stopSpeaking(): void {
    if ('speechSynthesis' in window) window.speechSynthesis.cancel()
    speaking.value = false
  }

  function speak(text: string): void {
    if (!text.trim()) return
    if (!('speechSynthesis' in window) || !('SpeechSynthesisUtterance' in window)) {
      error.value = '当前浏览器不支持语音播报，请直接阅读面试官的文字回复。'
      return
    }
    if (listening.value) stop()
    stopSpeaking()
    error.value = ''
    const utterance = new SpeechSynthesisUtterance(text)
    utterance.lang = 'zh-CN'
    utterance.rate = 1
    const chineseVoice = window.speechSynthesis.getVoices().find((voice) => voice.lang.toLowerCase().startsWith('zh'))
    if (chineseVoice) utterance.voice = chineseVoice
    utterance.onstart = () => { speaking.value = true }
    utterance.onend = () => { speaking.value = false }
    utterance.onerror = () => { speaking.value = false; error.value = '播报失败，可以点击“重播提问”再试。' }
    window.speechSynthesis.speak(utterance)
  }

  onBeforeUnmount(() => {
    recognition?.abort()
    stopSpeaking()
  })

  return {
    available: readonly(available), secureContext: readonly(secureContext),
    listening: readonly(listening), speaking: readonly(speaking),
    transcript, interim: readonly(interim), error: readonly(error), autoRead,
    start, stop, speak, stopSpeaking,
  }
}

import { computed, readonly, shallowRef } from 'vue'

import { api, errorMessage, MODEL_REQUEST_TIMEOUT_MS } from '@/lib/api'
import type { ApiEnvelope, TrainingPlan } from '@/lib/types'

export function useCourseLearning() {
  const plan = shallowRef<TrainingPlan | null>(null)
  const loading = shallowRef(true)
  const submitting = shallowRef(false)
  const error = shallowRef('')
  const courseTask = computed(() => plan.value?.tasks.find((task) => task.actionType === 'COURSE') ?? null)

  async function load(preferredPlanId = ''): Promise<void> {
    loading.value = true
    error.value = ''
    try {
      if (preferredPlanId) {
        plan.value = (await api.get<ApiEnvelope<TrainingPlan>>(`/training-plans/${preferredPlanId}`)).data.data
      } else {
        const plans = (await api.get<ApiEnvelope<TrainingPlan[]>>('/training-plans')).data.data
        plan.value = plans.find((item) => item.status === 'ACTIVE' && item.tasks.some((task) => task.lesson))
          ?? plans.find((item) => item.tasks.some((task) => task.lesson))
          ?? null
      }
    } catch (reason) {
      error.value = errorMessage(reason)
    } finally {
      loading.value = false
    }
  }

  async function completeStep(index: number): Promise<void> {
    if (!plan.value || !courseTask.value || submitting.value) return
    submitting.value = true
    error.value = ''
    try {
      const path = `/training-plans/${plan.value.id}/tasks/${courseTask.value.key}/steps/${index}/complete`
      plan.value = (await api.post<ApiEnvelope<TrainingPlan>>(path)).data.data
    } catch (reason) {
      error.value = errorMessage(reason)
    } finally {
      submitting.value = false
    }
  }

  async function completeCourse(): Promise<void> {
    if (!plan.value || !courseTask.value || submitting.value) return
    submitting.value = true
    error.value = ''
    try {
      const path = `/training-plans/${plan.value.id}/tasks/${courseTask.value.key}/course/complete`
      plan.value = (await api.post<ApiEnvelope<TrainingPlan>>(path)).data.data
    } catch (reason) {
      error.value = errorMessage(reason)
    } finally {
      submitting.value = false
    }
  }

  async function submitPractice(answer: string): Promise<void> {
    if (!plan.value || !courseTask.value || submitting.value) return
    submitting.value = true
    error.value = ''
    try {
      const path = `/training-plans/${plan.value.id}/tasks/${courseTask.value.key}/practice`
      plan.value = (await api.post<ApiEnvelope<TrainingPlan>>(path, { answer }, { timeout: MODEL_REQUEST_TIMEOUT_MS })).data.data
    } catch (reason) {
      error.value = errorMessage(reason)
    } finally {
      submitting.value = false
    }
  }

  return {
    plan: readonly(plan), courseTask, loading: readonly(loading), submitting: readonly(submitting),
    error: readonly(error), load, completeStep, completeCourse, submitPractice,
  }
}

