    controller = request
    loading.value = true
    error.value = ''
    try {
      const value = filters.value
      const response = await api.get<ApiEnvelope<DashboardData>>('/dashboard', { signal: request.signal, params: { channel: value.channel || undefined, scene_id: value.sceneId || undefined, anchor_session_id: value.anchorSessionId || undefined } })
      if (!request.signal.aborted) data.value = response.data.data
    } catch (reason) {
      if (!request.signal.aborted) error.value = errorMessage(reason)
    } finally {
      if (controller === request) loading.value = false
    }
  }

  function updateFilters(patch: Partial<DashboardFilters>) {
    filters.value = { ...filters.value, ...(('channel' in patch || 'sceneId' in patch) ? { anchorSessionId: '' } : {}), ...patch }
  }
  function resetFilters() { filters.value = { channel: '', sceneId: '', anchorSessionId: '' } }
  watch(filters, load)
  onMounted(load)
  onBeforeUnmount(() => controller?.abort())
  return { data, loading, error, filters, load, updateFilters, resetFilters }
}

import { inject, onBeforeUnmount, onMounted, readonly, shallowRef } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { api, authorizedFetch, errorMessage } from '@/lib/api'
import { activeTrainingAttemptKey } from '@/lib/activeTrainingAttempt'

/** A training attempt is temporary until the learner explicitly ends it. */
export function useInterviewExit(sessionId: () => string, retained: () => boolean, onError: (message: string) => void) {
  const controller = inject(activeTrainingAttemptKey)
  if (!controller) throw new Error('Training attempt controller must be provided by App')
  const leaving = shallowRef(false)
  let discarded = false
  let request: Promise<void> | null = null

  function clearDrafts(id: string): void {
    try {
      const prefix = `yanjie:draft:${id}:`
      for (let index = localStorage.length - 1; index >= 0; index--) {
        const key = localStorage.key(index)
        if (key?.startsWith(prefix)) localStorage.removeItem(key)
      }
    } catch { /* Storage can be unavailable in private browsing. */ }
  }

  async function discard(): Promise<void> {
    const id = sessionId()
    if (!id || retained() || discarded) return
    request ??= api.post(`/training-sessions/${id}/discard`).then(() => { discarded = true; clearDrafts(id) }).finally(() => { request = null })
    await request
  }

  function discardOnUnload(): void {
    const id = sessionId()
    if (!id || retained() || discarded) return
    clearDrafts(id)
    void authorizedFetch(`/training-sessions/${id}/discard`, { method: 'POST', keepalive: true }).catch(() => {})
  }

  async function cleanupBeforeLogout(): Promise<void> {
    try { await discard() }
    catch (reason) { onError(`退出清理未完成：${errorMessage(reason)}，请重试退出。`); throw reason }
  }

  onBeforeRouteLeave(async () => {
    leaving.value = true
    try {
      await discard()
      return true
    } catch (reason) {
      onError(`退出清理未完成：${errorMessage(reason)}，请重试退出。`)
      return false
    } finally {
      leaving.value = false
    }
  })
  const unregister = controller.register({ sessionId, retained, discard: cleanupBeforeLogout })
  onMounted(() => {
    window.addEventListener('pagehide', discardOnUnload)
  })
  onBeforeUnmount(() => {
    unregister()
    window.removeEventListener('pagehide', discardOnUnload)
    discardOnUnload()
  })
  return { leaving: readonly(leaving) }
}

import { shallowRef } from 'vue'

import { authorizedFetch } from '@/lib/api'

interface AvatarAudioTarget {
  observeAudio(analyser: AnalyserNode | null): void
  finishAudio(): void
  /** 数字人自己出声（回流带音轨）时为真：本地 TTS 只送不播，否则两路声音差约一秒。 */
  ownsAudio?: () => boolean
  /** 重听只能退回浏览器朗读时，向用户说明这一遍不驱动数字人口型。 */
  noticeReplayFallback?: (message: string) => void
}

/** 重听走浏览器 TTS 时口型拿不到音源，必须明说，不能假装在动。 */
const REPLAY_UNSYNCED_NOTICE = '本次重听不驱动数字人口型'

/** 数字人出声时，回流的末字比本地缓冲晚到约一秒：收尾要等这么久才算真说完。 */
const REMOTE_TAIL_MS = 1000

/** Owns playback resources only. Connection and upload lifecycle belongs to the room. */
export function useInterviewPlayback(avatar: () => AvatarAudioTarget | null, onSpeaking: () => void, onFinished: () => void) {
  const speakerActive = shallowRef(false)
  const replayActive = shallowRef(false)
  let context: AudioContext | null = null
  let analyser: AnalyserNode | null = null
  const nodes = new Set<AudioBufferSourceNode>()
  let replay: SpeechSynthesisUtterance | null = null
  let playbackAt = 0
  /** 本地是否直连扬声器。数字人接管出声后断开这条连接，音源仍照常流向数字人做口型。 */
  let localAudible = true
  let finishTimer = 0
  // 每次 stopPlayback 自增：在途的重听请求回来后发现自己过期就直接丢弃
  let replayToken = 0

  function playback(): AudioContext {
    if (!context) {
      context = new AudioContext({ sampleRate: 24000 })
      analyser = context.createAnalyser()
      analyser.fftSize = 256
      analyser.connect(context.destination)
    }
    if (context.state === 'suspended') void context.resume()
    return context
  }

  /** 数字人出声时掐掉本地扬声器这条路（AnalyserNode 的另一路仍喂口型），否则同一句话说两遍。 */
  function routeToAvatar(remote: boolean): void {
    const ctx = context
    if (!ctx || !analyser) return
    if (localAudible === !remote) return
    localAudible = !remote
    try {
      if (localAudible) analyser.connect(ctx.destination)
      else analyser.disconnect(ctx.destination)
    } catch { /* 本来就没连/已断开 */ }
  }

  function clearFinish(): void {
    if (finishTimer) { window.clearTimeout(finishTimer); finishTimer = 0 }
  }

  /** 数字人出声时最后一句还在路上，收尾要延后一个回流延迟，避免提前静音掐掉尾音。 */
  function settle(): void {
    clearFinish()
    const tail = localAudible ? 0 : REMOTE_TAIL_MS
    if (!tail) {
      speakerActive.value = false
      replayActive.value = false
      onFinished()
      return
    }
    finishTimer = window.setTimeout(() => {
      finishTimer = 0
      speakerActive.value = false
      replayActive.value = false
      onFinished()
    }, tail)
  }

  /**
   * 所有出声的音频都从这里进：接到同一个 AnalyserNode，
   * 数字人（Simli）与 3D 口型拿到的就是这一路，重听和正式播报没有分叉。
   */
  function queueBuffer(buffer: AudioBuffer, isReplay = false): void {
    const ctx = playback()
    routeToAvatar(avatar()?.ownsAudio?.() ?? false)
    avatar()?.observeAudio(analyser)
    const node = ctx.createBufferSource()
    node.buffer = buffer
    node.connect(analyser ?? ctx.destination)
    nodes.add(node)
    speakerActive.value = true
    if (isReplay) replayActive.value = true
    node.onended = () => {
      nodes.delete(node)
      if (!nodes.size) settle()
      node.disconnect()
    }
    playbackAt = Math.max(playbackAt, ctx.currentTime + 0.05)
    node.start(playbackAt)
    playbackAt += buffer.duration
    onSpeaking()
  }

  /**
   * 开口之前先把音源备好：数字人的口型靠这条 AnalyserNode 转发，
   * 等第一帧音频才建 tap 的话，先到的那句（开场提问）没有音源可转，只剩无声画面。
   */
  function preparePlayback(): void {
    const ctx = playback()
    routeToAvatar(avatar()?.ownsAudio?.() ?? false)
    if (analyser) avatar()?.observeAudio(analyser)
    if (ctx.state === 'suspended') void ctx.resume()
  }

  function queuePcm(samples: Float32Array): void {
    if (!samples.length) return
    const ctx = playback()
    const buffer = ctx.createBuffer(1, samples.length, 24000)
    buffer.copyToChannel(samples, 0)
    queueBuffer(buffer)
  }

  function toSamples(data: Uint8Array): Float32Array {
    const view = new DataView(data.buffer, data.byteOffset, data.byteLength)
    const samples = new Float32Array(Math.floor(data.byteLength / 2))
    for (let i = 0; i < samples.length; i++) samples[i] = view.getInt16(i * 2, true) / 32768
    return samples
  }

  function playPcm(base64: string): void {
    const binary = atob(base64)
    const bytes = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
    queuePcm(toSamples(bytes))
  }
  function playPcmBinary(data: ArrayBuffer): void { queuePcm(toSamples(new Uint8Array(data))) }

  /** 重听取后端 TTS 预览的音频（与正式播报同一个合成器），解出 AudioBuffer 后走同一条播放链路。 */
  async function loadReplayBuffer(text: string, token: number): Promise<AudioBuffer | null> {
    try {
      const response = await authorizedFetch('/scripts/preview', {
        method: 'POST',
        body: JSON.stringify({ text }),
      })
      if (!response.ok) return null
      const payload = await response.json() as { data?: { url?: string } }
      const url = payload?.data?.url
      if (!url) return null
      const audio = await fetch(url, { credentials: 'include' })
      if (!audio.ok) return null
      const bytes = await audio.arrayBuffer()
      // 期间房间已关闭/被打断：别再为这遍重听新建 AudioContext
      if (token !== replayToken) return null
      const buffer = await playback().decodeAudioData(bytes)
      return buffer && buffer.duration > 0 ? buffer : null
    } catch { return null }
  }

  function stopPlayback(): void {
    replayToken += 1
    clearFinish()
    avatar()?.finishAudio()
    replay = null
    replayActive.value = false
    if ('speechSynthesis' in window) window.speechSynthesis.cancel()
    for (const node of nodes) {
      node.onended = null
      try { node.stop() } catch { /* Already ended. */ }
      node.disconnect()
    }
    nodes.clear()
    speakerActive.value = false
    playbackAt = 0
  }

  /** 只有 TTS 预览不可用才退回浏览器朗读，并明说这一遍不驱动口型。 */
  function speakWithBrowser(text: string): void {
    avatar()?.noticeReplayFallback?.(REPLAY_UNSYNCED_NOTICE)
    if (!('speechSynthesis' in window)) return
    const utterance = new SpeechSynthesisUtterance(text)
    replay = utterance
    utterance.lang = 'zh-CN'
    utterance.rate = 0.92
    utterance.onstart = () => { if (replay === utterance) replayActive.value = true }
    const done = () => { if (replay === utterance) { replayActive.value = false; replay = null } }
    utterance.onend = done
    utterance.onerror = done
    window.speechSynthesis.speak(utterance)
  }

  async function replaySpeech(text: string): Promise<void> {
    if (!text) return
    stopPlayback()
    const token = replayToken
    const buffer = await loadReplayBuffer(text, token)
    // 期间被打断/又点了重听：这遍直接作废，不叠音
    if (token !== replayToken) return
    if (buffer) { queueBuffer(buffer, true); return }
    speakWithBrowser(text)
  }

  function disposePlayback(): void {
    stopPlayback()
    void context?.close()
    context = null
    analyser = null
  }
  function resumePlayback(): void { if (context?.state === 'suspended') void context.resume() }
  return { speakerActive, replayActive, playPcm, playPcmBinary, replaySpeech, stopPlayback, disposePlayback, resumePlayback, preparePlayback,
    playbackExpired: () => playbackAt <= (context?.currentTime ?? 0) }
}

/** Captures the user's stream and owns the final MediaRecorder data boundary. */
export function useInterviewRecording() {
  let recorder: MediaRecorder | null = null
  let chunks: Blob[] = []
  let mimeType = 'audio/webm'
  function startRecording(stream: MediaStream, video: boolean): void {
    if (typeof MediaRecorder === 'undefined') return
    chunks = []
    const currentChunks = chunks
    mimeType = video ? 'video/webm' : 'audio/webm'
    const mime = video && MediaRecorder.isTypeSupported('video/webm;codecs=vp8,opus') ? 'video/webm;codecs=vp8,opus' : undefined
    recorder = new MediaRecorder(stream, mime ? { mimeType: mime } : undefined)
    recorder.ondataavailable = event => { if (event.data.size) currentChunks.push(event.data) }
    recorder.start(1000)
  }
  async function finishRecording(): Promise<void> {
    if (!recorder || recorder.state === 'inactive') return
    const current = recorder
    await new Promise<void>(resolve => {
      current.addEventListener('stop', () => resolve(), { once: true })
      current.stop()
    })
  }
  function stopRecording(): void {
    try { if (recorder && recorder.state !== 'inactive') recorder.stop() } catch { /* Already stopped. */ }
    recorder = null
  }
  return { startRecording, finishRecording, stopRecording,
    recordingBlob: () => chunks.length ? new Blob(chunks, { type: mimeType }) : null }
}

import { shallowRef } from 'vue'
import { api, MODEL_REQUEST_TIMEOUT_MS } from '@/lib/api'
import type { ApiEnvelope } from '@/lib/types'

export interface InterviewSubmission {
  sceneId: string
  preparedSessionId: string
  turns: Array<{ question: string; answer: string; startMs?: number; endMs?: number }>
  engine: string
  channelHint: 'VOICE' | 'VIDEO'
  durationSeconds: number
  recording: Blob | null
}

/** An uploaded answer set is reused when report generation must be retried. */
export function useInterviewSubmission() {
  const uploadedSessionId = shallowRef('')
  const submissionStage = shallowRef<'notUploaded' | 'uploaded' | 'reportReady'>('notUploaded')
  async function submitReport(input: InterviewSubmission): Promise<string> {
    if (!uploadedSessionId.value) {
      const form = new FormData()
      form.append('sceneId', input.sceneId)
      form.append('preparedSessionId', input.preparedSessionId)
      form.append('turns', JSON.stringify(input.turns))
      form.append('engine', input.engine)
      form.append('channelHint', input.channelHint)
      form.append('durationSeconds', String(input.durationSeconds))
      if (input.recording) form.append(input.channelHint === 'VIDEO' ? 'video' : 'audio', input.recording, 'interview.webm')
      const saved = await api.post<ApiEnvelope<{ id: string }>>('/voice/sessions', form, { timeout: 180000 })
      uploadedSessionId.value = saved.data.data.id
      submissionStage.value = 'uploaded'
    }
    await api.post(`/training-sessions/${uploadedSessionId.value}/finish`, null, { timeout: MODEL_REQUEST_TIMEOUT_MS })
    submissionStage.value = 'reportReady'
    return uploadedSessionId.value
  }
  return { uploadedSessionId, submissionStage, submitReport }
}

import { onMounted, onUnmounted, readonly, shallowRef } from 'vue'

export function useNetworkStatus() {
  const isOnline = shallowRef(navigator.onLine)

  function markOnline() {
    isOnline.value = true
  }

  function markOffline() {
    isOnline.value = false
  }

  onMounted(() => {
    window.addEventListener('online', markOnline)
    window.addEventListener('offline', markOffline)
  })

  onUnmounted(() => {
    window.removeEventListener('online', markOnline)
    window.removeEventListener('offline', markOffline)
  })

  return { isOnline: readonly(isOnline) }
}

import { computed, shallowRef, watch, type ShallowRef } from 'vue'
import { useRoute } from 'vue-router'

import type { Scene } from '@/lib/types'
import { DIFFICULTY_LEVELS, normalizeSceneCategory, SCENE_CATEGORIES, isFoundationScene } from '@/lib/sceneTaxonomy'

export function useSceneFilters(scenes: ShallowRef<Scene[]>) {
  const route = useRoute()
  const activeCategory = shallowRef(normalizeSceneCategory(String(route.query.category ?? '全部')))
  const activeIndustry = shallowRef('全部行业')
  const activePosition = shallowRef('全部岗位')
  const activeDifficulty = shallowRef('全部难度')
  const query = shallowRef('')

  const planId = computed(() => String(route.query.planId ?? ''))
  const taskKey = computed(() => String(route.query.taskKey ?? ''))
  const recommendedSceneId = computed(() => String(route.query.sceneId ?? ''))
  const foundationFocus = computed(() => isFoundationScene(recommendedSceneId.value))
  const catalogScenes = computed(() => scenes.value.filter((scene) =>
    (!scene.mine || scene.id === recommendedSceneId.value) && (!isFoundationScene(scene.id) || (foundationFocus.value && scene.id === recommendedSceneId.value))))
  const industries = computed(() => ['全部行业', ...new Set(catalogScenes.value
    .filter((scene) => !isFoundationScene(scene.id)).map((scene) => scene.industry))])
  const industryScenes = computed(() => catalogScenes.value.filter((scene) =>
    activeIndustry.value === '全部行业' || scene.industry === activeIndustry.value || scene.industry === '综合行业'))
  const positions = computed(() => ['全部岗位', ...new Set(catalogScenes.value
    .filter((scene) => activeIndustry.value === '全部行业' || scene.industry === activeIndustry.value)
    .map((scene) => scene.position))])
  const positionScenes = computed(() => industryScenes.value.filter((scene) =>
    activePosition.value === '全部岗位' || scene.position === activePosition.value || scene.position === '应届毕业生'))
  const categories = computed(() => {
    const available = new Set(positionScenes.value.map((scene) => scene.category))
    return SCENE_CATEGORIES.filter((category) => category === '全部' || available.has(category))
  })
  const categoryScenes = computed(() => positionScenes.value.filter((scene) =>
    activeCategory.value === '全部' || scene.category === activeCategory.value))
  const difficulties = computed(() => {
    const available = new Set(categoryScenes.value.map((scene) => scene.difficulty))
    return ['全部难度', ...DIFFICULTY_LEVELS.map((level) => level.name).filter((name) => available.has(name))]
  })
  const visibleScenes = computed(() => categoryScenes.value
    .filter((scene) => {
      if (recommendedSceneId.value && scene.id !== recommendedSceneId.value) return false
      if (activeDifficulty.value !== '全部难度' && scene.difficulty !== activeDifficulty.value) return false
      const text = `${scene.title}${scene.background}${scene.tags.join('')}${scene.industry}${scene.position}${scene.roleName}`.toLowerCase()
      return text.includes(query.value.trim().toLowerCase())
    })
    .sort((a, b) => SCENE_CATEGORIES.indexOf(a.category as (typeof SCENE_CATEGORIES)[number])
      - SCENE_CATEGORIES.indexOf(b.category as (typeof SCENE_CATEGORIES)[number])
      || DIFFICULTY_LEVELS.findIndex((level) => level.name === a.difficulty)
      - DIFFICULTY_LEVELS.findIndex((level) => level.name === b.difficulty)))

  watch(() => route.query.category, (category) => {
    activeCategory.value = normalizeSceneCategory(String(category ?? '全部'))
  })
  watch(() => route.query.sceneId, () => {
    activeCategory.value = '全部'
    activeIndustry.value = '全部行业'
    activePosition.value = '全部岗位'
    activeDifficulty.value = '全部难度'
    query.value = ''
  })
  watch(categories, () => {
    if (!categories.value.includes(activeCategory.value as (typeof SCENE_CATEGORIES)[number])) activeCategory.value = '全部'
  })
  watch(activeIndustry, () => {
    activePosition.value = '全部岗位'
    activeDifficulty.value = '全部难度'
  })
  watch(activePosition, () => { activeDifficulty.value = '全部难度' })
  watch(activeCategory, () => { activeDifficulty.value = '全部难度' })

  return {
    activeCategory, activeIndustry, activePosition, activeDifficulty, query,
    categories, industries, positions, difficulties, visibleScenes, catalogScenes, foundationFocus,
    planId, taskKey, recommendedSceneId,
  }
}

import { onBeforeUnmount, shallowRef } from 'vue'

import { api, errorMessage } from '@/lib/api'
import type { ApiEnvelope, ScriptVersion } from '@/lib/types'

export function useScriptPreview(setError: (message: string) => void) {
  const previewingId = shallowRef('')
  const playingId = shallowRef('')
  let audio: HTMLAudioElement | null = null
  let controller: AbortController | null = null

  function stopAudio() {
    if (audio) {
      audio.onended = null
      audio.onerror = null
      audio.pause()
      audio = null
    }
    playingId.value = ''
  }

  async function playPreview(version: ScriptVersion): Promise<void> {
    if (playingId.value === version.id) { stopAudio(); return }
    if (previewingId.value) return
    stopAudio()
    setError('')
    previewingId.value = version.id
    const request = new AbortController()
    controller = request
    try {
      const response = await api.post<ApiEnvelope<{ url: string }>>('/scripts/preview', { text: version.content }, { signal: request.signal })
      if (request.signal.aborted) return
      audio = new Audio(response.data.data.url)
      audio.onended = stopAudio
      audio.onerror = () => { stopAudio(); setError('试听音频加载失败，请稍后重试。') }
      try {
        await audio.play()
        playingId.value = version.id
      } catch {
        stopAudio()
        setError('试听播放失败，请检查浏览器声音权限后重试。')
      }
    } catch (reason) {
      if (!request.signal.aborted) setError(errorMessage(reason))
    } finally {
      previewingId.value = ''
      controller = null
    }
  }

  onBeforeUnmount(() => { controller?.abort(); stopAudio() })
  return { previewingId, playingId, playPreview }
}

import { readonly, shallowRef } from 'vue'

type Theme = 'dark' | 'light'
type Scope = 'STUDENT' | 'ADMIN' | null

const BASE_KEY = 'yanjie-theme'
const theme = shallowRef<Theme>((document.documentElement.dataset.theme as Theme) || 'dark')
let scope: Scope = null

function storageKey(target: Scope): string {
  return target ? `${BASE_KEY}:${target}` : BASE_KEY
}

function readSaved(target: Scope): Theme | null {
  try {
    const value = localStorage.getItem(storageKey(target))
    return value === 'dark' || value === 'light' ? value : null
  } catch {
    return null
  }
}

function systemTheme(): Theme {
  try {
    return window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark'
  } catch {
    return 'dark'
  }
}

function apply(next: Theme, persist = true): void {
  theme.value = next
  document.documentElement.dataset.theme = next
  const meta = document.querySelector('meta[name="theme-color"]')
  if (meta) meta.setAttribute('content', next === 'light' ? '#f5f3ee' : '#0b0e13')
  if (!persist) return
  try {
    localStorage.setItem(storageKey(scope), next)
  } catch {
    // 隐私模式下忽略
  }
}

export function useTheme() {
  return {
    theme: readonly(theme),
    setScope: (next: Scope) => {
      scope = next
    },
    currentScope: () => scope,
    savedFor: readSaved,
    systemTheme,
    toggle: () => apply(theme.value === 'dark' ? 'light' : 'dark'),
    setTheme: apply,
    applyTemporary: (next: Theme) => apply(next, false),
    /** 切换登录角色时套用该角色自己的偏好 */
    applyScope: (next: Scope) => {
      scope = next
      const saved = readSaved(next)
      if (saved) apply(saved, false)
    },
  }
}

import { readonly, shallowRef } from 'vue'

import { api, errorMessage } from '@/lib/api'
import type { ApiEnvelope, TrainingPlan } from '@/lib/types'

export function useTrainingPlan(planId: string) {
  const plan = shallowRef<TrainingPlan | null>(null)
  const loading = shallowRef(false)
  const submitting = shallowRef(false)
  const error = shallowRef('')

  async function load(): Promise<void> {
    loading.value = true
    error.value = ''
    try {
      const response = await api.get<ApiEnvelope<TrainingPlan>>(`/training-plans/${planId}`)
      plan.value = response.data.data
    } catch (reason) {
      error.value = errorMessage(reason)
    } finally {
      loading.value = false
    }
  }

  async function complete(taskKey: string, evidence?: string): Promise<void> {
    submitting.value = true
    error.value = ''
    try {
      const response = await api.post<ApiEnvelope<TrainingPlan>>(
        `/training-plans/${planId}/tasks/${taskKey}/complete`,
        { evidence: evidence || null },
      )
      plan.value = response.data.data
    } catch (reason) {
      error.value = errorMessage(reason)
      throw reason
    } finally {
      submitting.value = false
    }
  }

  return {
    plan: readonly(plan),
    loading: readonly(loading),
    submitting: readonly(submitting),
    error: readonly(error),
    load,
    complete,
  }
}

import { shallowRef } from 'vue'
import { api, errorMessage } from '@/lib/api'
import type { ApiEnvelope, Evaluation, TrainingMessage, TrainingSession } from '@/lib/types'

export function useTrainingReport(sessionId: () => string) {
  const evaluation = shallowRef<Evaluation | null>(null)
  const messages = shallowRef<TrainingMessage[]>([])
  const session = shallowRef<TrainingSession | null>(null)
  const error = shallowRef('')
  const rescoring = shallowRef(false)

  async function loadReport(): Promise<void> {
    const response = await api.get<ApiEnvelope<Evaluation>>(`/evaluations/${sessionId()}`)
    const sessionResponse = await api.get<ApiEnvelope<TrainingSession>>(`/training-sessions/${sessionId()}`).catch(() => null)
    if (sessionResponse) {
      session.value = sessionResponse.data.data
      messages.value = sessionResponse.data.data.messages
    }
    evaluation.value = response.data.data
  }

  async function rescore(): Promise<void> {
    if (rescoring.value) return
    rescoring.value = true
    error.value = ''
    try {
      await api.post(`/evaluations/${sessionId()}?force=true`)
      await loadReport()
    } catch (reason) { error.value = errorMessage(reason) }
    finally { rescoring.value = false }
  }
  return { evaluation, messages, session, error, rescoring, loadReport, rescore }
}

import { readonly, shallowRef } from 'vue'

import { api, errorMessage, MODEL_REQUEST_TIMEOUT_MS } from '@/lib/api'
import type { ApiEnvelope, Evaluation, TrainingMessage, TrainingSession } from '@/lib/types'

export function useTrainingSession(sessionId: string) {
  const session = shallowRef<TrainingSession | null>(null)
  const sending = shallowRef(false)
  const error = shallowRef('')
  const liveFlags = shallowRef<string[]>([])
  const degraded = shallowRef(false)

  async function load(): Promise<void> {
    const response = await api.get<ApiEnvelope<TrainingSession>>(`/training-sessions/${sessionId}`)
    session.value = response.data.data
  }

  async function send(content: string, finishAfterReply = false): Promise<void> {
    if (!session.value || sending.value) return
    error.value = ''
    liveFlags.value = []
    degraded.value = false
    sending.value = true
    const roundNo = session.value.currentRound + 1
    const userMessage: TrainingMessage = {
      id: `local-user-${Date.now()}`,
      roundNo,
      speaker: 'USER',
      content,
      flagged: false,
      flags: [],
      createdAt: new Date().toISOString(),
    }
    const aiMessage: TrainingMessage = {
      id: `local-ai-${Date.now()}`,
      roundNo,
      speaker: 'AI',
      content: '',
      flagged: false,
      flags: [],
      createdAt: new Date().toISOString(),
    }
    session.value = { ...session.value, messages: [...session.value.messages, userMessage, aiMessage] }
    try {
      const response = await api.post<ApiEnvelope<{
        roundNo: number; stage: string; flags: string[]; messageId: string
        content: string; finished: boolean; degraded: boolean
        questionTotal?: number; questionCovered?: number; coveredQuestionIndexes?: number[]
      }>>(`/training-sessions/${sessionId}/messages/complete`, { content, finishAfterReply }, { timeout: MODEL_REQUEST_TIMEOUT_MS })
      const turn = response.data.data
      liveFlags.value = turn.flags
      degraded.value = turn.degraded
      if (session.value) session.value = {
        ...session.value,
        currentRound: turn.roundNo,
        stage: turn.stage,
        status: turn.finished ? 'FINISHED' : session.value.status,
        questionTotal: turn.questionTotal ?? session.value.questionTotal,
        questionCovered: turn.questionCovered ?? session.value.questionCovered,
        coveredQuestionIndexes: turn.coveredQuestionIndexes ?? session.value.coveredQuestionIndexes,
        conditionsEditable: turn.roundNo > 0 || turn.finished ? false : session.value.conditionsEditable,
        conditionsLockedReason: turn.finished ? '本场面试已结束，岗位和题目已固定；如需调整，请开始新的训练。'
          : turn.roundNo > 0 ? '已开始作答，岗位和题目已固定；如需调整，请开始新的训练。' : session.value.conditionsLockedReason,
        messages: session.value.messages.map((message) => {
          if (message.id === userMessage.id) return { ...message, roundNo: turn.roundNo, flagged: turn.flags.length > 0, flags: turn.flags }
          if (message.id === aiMessage.id) return { ...message, id: turn.messageId, roundNo: turn.roundNo, content: turn.content }
          return message
        }),
      }
    } catch (reason) {
      error.value = errorMessage(reason)
      try { await load() } catch { /* Preserve the visible draft if reconnection also fails. */ }
    } finally {
      sending.value = false
    }
  }

  async function finish(createPlan = true): Promise<Evaluation> {
    const response = await api.post<ApiEnvelope<Evaluation>>(
      `/training-sessions/${sessionId}/finish`,
      null,
      { params: { create_plan: createPlan }, timeout: MODEL_REQUEST_TIMEOUT_MS },
    )
    if (session.value) session.value = { ...session.value, status: 'FINISHED' }
    return response.data.data
  }

  async function restart(): Promise<string> {
    const response = await api.post<ApiEnvelope<TrainingSession>>(`/training-sessions/${sessionId}/restart`, null)
    return response.data.data.id
  }

  return { session: readonly(session), sending: readonly(sending), error: readonly(error), liveFlags: readonly(liveFlags), degraded: readonly(degraded), load, send, finish, restart }
}

