export interface DiffSegment {
  type: 'same' | 'add' | 'del'
  text: string
}

const MAX_CHARS = 900

/**
 * 字符级 LCS 差异。用于话术版本与用户原话的逐字对比。
 * 超过 MAX_CHARS 时退化为整段标记，避免 O(n²) 卡顿。
 */
export function diffChars(base: string, next: string): DiffSegment[] {
  const a = Array.from(base)
  const b = Array.from(next)
  if (!a.length) return b.length ? [{ type: 'add', text: next }] : []
  if (!b.length) return [{ type: 'del', text: base }]
  if (a.length * b.length > MAX_CHARS * MAX_CHARS / 4) {
    return [{ type: 'del', text: base }, { type: 'add', text: next }]
  }

  const m = a.length
  const n = b.length
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array<number>(n + 1).fill(0))
  for (let i = m - 1; i >= 0; i -= 1) {
    for (let j = n - 1; j >= 0; j -= 1) {
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const out: DiffSegment[] = []
  const push = (type: DiffSegment['type'], text: string) => {
    if (!text) return
    const last = out[out.length - 1]
    if (last && last.type === type) last.text += text
    else out.push({ type, text })
  }

  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (a[i] === b[j]) {
      push('same', a[i])
      i += 1
      j += 1
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      push('del', a[i])
      i += 1
    } else {
      push('add', b[j])
      j += 1
    }
  }
  while (i < m) {
    push('del', a[i])
    i += 1
  }
  while (j < n) {
    push('add', b[j])
    j += 1
  }
  return out
}

export function diffStats(segments: DiffSegment[]): { added: number; removed: number } {
  let added = 0
  let removed = 0
  for (const segment of segments) {
    const length = Array.from(segment.text).length
    if (segment.type === 'add') added += length
    if (segment.type === 'del') removed += length
  }
  return { added, removed }
}

/** 前端错误上报：白屏、未捕获异常、Promise 拒绝都留下信号。 */

interface ReportPayload {
  message: string
  stack?: string
  route?: string
  userAgent?: string
}

const seen = new Set<string>()
const MAX_REPORTS_PER_LOAD = 10

function send(payload: ReportPayload): void {
  const key = `${payload.message}|${payload.route ?? ''}`.slice(0, 200)
  if (seen.has(key) || seen.size >= MAX_REPORTS_PER_LOAD) return
  seen.add(key)

  try {
    void fetch('/api/v1/client-errors', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Referer: location.origin + '/' },
      body: JSON.stringify(payload),
      keepalive: true,
    }).catch(() => undefined)
  } catch {
    // 上报失败不能影响页面
  }
}

export function reportClientError(error: unknown, context = ''): void {
  const route = typeof location !== 'undefined' ? location.pathname : undefined
  if (error instanceof Error) {
    send({ message: `${context}${error.message}`.slice(0, 300), stack: error.stack?.slice(0, 2000), route, userAgent: navigator.userAgent.slice(0, 300) })
  } else {
    send({ message: `${context}${String(error)}`.slice(0, 300), route, userAgent: navigator.userAgent.slice(0, 300) })
  }
}

export function installErrorReporting(): void {
  if (typeof window === 'undefined') return

  window.addEventListener('error', (event) => {
    // 资源加载失败没有 error 对象，也要记录
    const target = event.target as HTMLElement | null
    if (target && target !== (window as unknown as HTMLElement) && target.tagName) {
      reportClientError(`资源加载失败: ${target.tagName}`, '')
      return
    }
    reportClientError(event.error ?? event.message, 'window.error: ')
  })

  window.addEventListener('unhandledrejection', (event) => {
    reportClientError(event.reason, 'unhandledrejection: ')
  })
}

export interface ExpressionWarning {
  label: string
  phrase: string
  start: number
  end: number
}

const patterns: Record<string, string[]> = {
  命令式表达: ['你必须', '少废话', '照我说的做'],
  推卸责任: ['不关我的事', '都是他们的问题', '我没办法'],
  绝对化表达: ['绝对不可能', '你总是', '你从来不'],
}

export function findExpressionWarnings(text: string): ExpressionWarning[] {
  const matches: ExpressionWarning[] = []
  for (const [label, phrases] of Object.entries(patterns)) {
    for (const phrase of phrases) {
      let index = text.indexOf(phrase)
      while (index !== -1) {
        matches.push({ label, phrase, start: index, end: index + phrase.length })
        index = text.indexOf(phrase, index + phrase.length)
      }
    }
  }
  return matches.sort((left, right) => left.start - right.start || right.end - left.end)
}

import type { Application } from 'pixi.js'

export type LocalAvatar = {
  observeAudio: (source: AnalyserNode | null) => void
  setSpeaking: (value: boolean) => void
  setListening: (value: boolean) => void
  setActive: (value: boolean) => void
  destroy: () => void
}

let coreLoading: Promise<void> | null = null

function loadCore(): Promise<void> {
  if ((window as Window & { Live2DCubismCore?: unknown }).Live2DCubismCore) return Promise.resolve()
  if (coreLoading) return coreLoading
  coreLoading = new Promise<void>((resolve, reject) => {
    const script = document.createElement('script')
    script.src = '/avatars/live2d/live2dcubismcore.min.js'
    script.onload = () => resolve()
    script.onerror = () => { script.remove(); coreLoading = null; reject(new Error('Live2D runtime unavailable')) }
    document.head.append(script)
  })
  return coreLoading
}

/** 本地渲染；只读取播放音轨的音量，不负责播放或发送音频。 */
export async function createLocalAvatar(container: HTMLElement): Promise<LocalAvatar> {
  await loadCore()
  const [{ Application, Ticker }, { Live2DModel, MotionPreloadStrategy }] = await Promise.all([
    import('pixi.js'), import('pixi-live2d-display/cubism4'),
  ])
  Live2DModel.registerTicker(Ticker)
  const app: Application = new Application({
    width: Math.max(64, container.clientWidth), height: Math.max(64, container.clientHeight),
    backgroundAlpha: 0, antialias: true, autoDensity: true,
    resolution: Math.min(window.devicePixelRatio || 1, 2), powerPreference: 'low-power',
  })
  app.ticker.maxFPS = 30
  try {
    const model = await Live2DModel.from('/avatars/live2d/hiyori/Hiyori.model3.json', {
      autoInteract: false, autoUpdate: false, idleMotionGroup: '', motionPreload: MotionPreloadStrategy.NONE,
    })
    app.stage.addChild(model)
    container.append(app.view)
    model.anchor.set(.5, 0)
    let analyser: AnalyserNode | null = null
    let samples = new Float32Array(256)
    let speaking = false
    let listening = false
    let active = true
    let mouth = 0
    let elapsed = 0
    const reduced = matchMedia('(prefers-reduced-motion: reduce)')
    const internal = model.internalModel
    const core = internal.coreModel as { setParameterValueById: (id: string, value: number) => void }
    const resize = () => {
      const width = Math.max(64, container.clientWidth), height = Math.max(64, container.clientHeight)
      app.renderer.resize(width, height)
      const scale = Math.min(width / (internal.width * .38), height / (internal.height * .32))
      model.scale.set(scale)
      model.position.set(width / 2, -height * .10)
    }
    const observer = new ResizeObserver(resize)
    observer.observe(container)
    resize()
    internal.on('beforeModelUpdate', () => {
      const still = reduced.matches || !active
      core.setParameterValueById('ParamMouthOpenY', mouth)
      core.setParameterValueById('ParamMouthForm', .35)
      core.setParameterValueById('ParamAngleX', still ? 0 : Math.sin(elapsed * .55) * 2)
      core.setParameterValueById('ParamAngleY', still ? 0 : Math.sin(elapsed * .7) * (listening ? 1.4 : .7))
      core.setParameterValueById('ParamAngleZ', still ? 0 : Math.sin(elapsed * .38) * 1.2)
      core.setParameterValueById('ParamBodyAngleX', still ? 0 : Math.sin(elapsed * .35) * .8)
      if (still) {
        core.setParameterValueById('ParamBreath', .5)
        core.setParameterValueById('ParamEyeLOpen', 1)
        core.setParameterValueById('ParamEyeROpen', 1)
      }
    })
    app.ticker.add(() => {
      const dt = Math.min(100, app.ticker.deltaMS)
      elapsed += dt / 1000
      let target = 0
      if (analyser && analyser.context.state === 'running') {
        analyser.getFloatTimeDomainData(samples)
        let energy = 0
        for (const value of samples) energy += value * value
        target = Math.min(1, Math.max(0, (Math.sqrt(energy / samples.length) - .006) * 8))
      } else if (speaking) {
        // 浏览器语音后备无法取得音轨，仅按说话状态作辅助动作。
        target = .15 + Math.abs(Math.sin(elapsed * 11)) * .35
      }
      mouth += (target - mouth) * (1 - Math.exp(-dt / (target > mouth ? 45 : 85)))
      model.update(dt)
    })
    const visibility = () => { if (document.hidden) app.stop(); else app.start() }
    document.addEventListener('visibilitychange', visibility)
    visibility()
    return {
      observeAudio(source) {
        analyser = source
        if (source) samples = new Float32Array(source.fftSize)
        else mouth = 0
      },
      setSpeaking(value) { speaking = value },
      setListening(value) { listening = value },
      setActive(value) { active = value },
      destroy() {
        observer.disconnect()
        document.removeEventListener('visibilitychange', visibility)
        analyser = null
        app.destroy(true, { children: true, texture: true, baseTexture: true })
      },
    }
  } catch (error) {
    app.destroy(true, { children: true, texture: true, baseTexture: true })
    throw error
  }
}

import type { TrainingPlanTask } from './types'

export function taskActionLabel(task: TrainingPlanTask): string {
  if (task.actionType === 'COURSE') {
    return task.learningProgress > 0 ? '继续学习微课' : '学习微课（3 个步骤）'
  }
  if (task.actionType === 'VOICE') return '用语音重答这一题'
  if (task.actionType === 'REPORT') return '回看本场复盘'
  if (task.actionType === 'TRAINING') return '进入专项场景对练'
  if (task.actionType === 'REWRITE') return '提交逐轮改写'
  return '按原条件复测'
}

export function taskRoute(planId: string, task: TrainingPlanTask) {
  const query = { planId, taskKey: task.key, ...(task.actionType === 'RETEST' ? { channel: task.channel ?? 'TEXT', depth: task.depth ?? 'STANDARD' } : {}) }
  if (task.actionType === 'COURSE') {
    return { name: 'plan-lesson', query: { ...query, courseId: task.courseId ?? undefined } }
  }
  if (task.actionType === 'SCENE') {
    return { name: 'scenes', query: { ...query, sceneId: task.sceneId ?? undefined } }
  }
  if (task.actionType === 'VIDEO') {
    return { name: 'video', query: { ...query, sceneId: task.sceneId ?? undefined } }
  }
  if (task.actionType === 'VOICE') {
    return { name: 'voice', query: { ...query, sceneId: task.sceneId ?? undefined } }
  }
  if (task.actionType === 'REPORT' && task.sourceSessionId) {
    return { name: 'report', params: { id: task.sourceSessionId } }
  }
  if (task.actionType === 'REWRITE') return { name: 'training-plan', params: { id: planId }, hash: '#rewrite-task' }
  if (task.actionType === 'REVIEW') {
    return { name: 'scripts' }
  }
  if (task.actionType === 'TRAINING' || task.actionType === 'RETEST') {
    return { name: 'scenes', query: { ...query, sceneId: task.sceneId ?? undefined } }
  }
  return null
}

export function stepTitle(task: TrainingPlanTask): string {
  if (task.actionType === 'COURSE') return '专项练习 · 学习微课'
  if (task.actionType === 'SCENE') return '能力匹配 · 场景复练'
  if (task.actionType === 'VIDEO') return '本场之后 · 视频重答'
  if (task.actionType === 'VOICE') return '本场之后 · 语音重答'
  if (task.actionType === 'REPORT') return '本场之后 · 回看复盘'
  if (task.actionType === 'REWRITE') return '本场之后 · 话术改写'
  if (task.actionType === 'REVIEW') return '间隔复习 · 到期错题'
  if (task.actionType === 'TRAINING') return '专项练习 · 场景对练'
  return '同场景复测 · 前后对比'
}

import type { QuestionRubric } from './contracts/interviewAssessment'

export function importedRubric(value: unknown): QuestionRubric | null {
  if (value === undefined || value === null) return null
  if (typeof value !== 'object' || !('competency' in value) || typeof value.competency !== 'string') throw new Error('考察标准需要 competency 名称。')
  const row = value as Record<string, unknown>
  const list = (key: string): string[] => {
    const items = row[key] ?? []
    if (!Array.isArray(items) || items.some(item => typeof item !== 'string')) throw new Error(`${key} 需要文字数组。`)
    return items as string[]
  }
  return { competency: value.competency, version: typeof row.version === 'string' ? row.version : 'v1',
    requiredPoints: list('requiredPoints'), acceptableVariants: list('acceptableVariants'), commonMistakes: list('commonMistakes'),
    transferQuestions: list('transferQuestions'), referenceUrl: typeof row.referenceUrl === 'string' ? row.referenceUrl : null,
    reviewed: row.reviewed === true }
}

